actions.script:
const day = /^\d{4}-\d{2}-\d{2}/.test(String(date || '')) ? String(date).substring(0, 10) : ec.l10n.format(ec.user.nowTimestamp, 'yyyy-MM-dd')
const pattern = 'yyyy-MM-dd HH:mm:ss.SSS'
const dayStart = ec.l10n.parseTimestamp(day + ' 00:00:00.000', pattern)
dayText = ec.l10n.format(ec.l10n.parseTimestamp(day + ' 12:00:00.000', pattern), 'EEEE, MMM d, yyyy')
const [year, month, dayOfMonth] = day.split('-').map(Number)
const dayAfter = (count) => new Date(Date.UTC(year, month - 1, dayOfMonth + count)).toISOString().substring(0, 10)
previousDay = dayAfter(-1)
nextDay = dayAfter(1)
const startMs = Number(String(dayStart))
const resources = Array.from(ec.resource.script('component://mr-boss/service/ironstone/maintenance/Maintenance.js')
        .execute('calendarResources', {resourceType: 'all'}).resourceList).slice(0, 50)
resourceRows = resources.map((resource) => ({name: resource.name, typeLabel: resource.typeLabel || '', site: resource.site || '',
    policyText: resource.policyText || '', facilityId: resource.resourceType === 'room' ? resource.resourceId : null,
    assetId: resource.resourceType === 'equipment' ? resource.resourceId : null}))
intervalRows = []
for (const resource of resourceRows) {
    ec.message.pushErrors()
    try {
        const read = ec.service.sync().name('mantle.work.ResourceBookingServices.get#ResourceAvailability').parameters({facilityId: resource.facilityId,
            assetId: resource.assetId, fromDate: new Date(startMs), thruDate: new Date(startMs + 86400000)}).call()
        if (!ec.message.hasError()) for (const row of Array.from(read?.intervalList || []))
            intervalRows.push({sortKey: String(row.fromText) + '|' + resource.name, timeText: row.fromText + ' – ' + row.thruText,
                resourceName: resource.name, kindText: row.kindText, label: row.label})
    } catch (err) {
        ec.logger.warn(`Availability of ${resource.name} not read: ${err && err.message ? err.message : err}`)
    } finally { ec.message.clearErrors(); ec.message.popErrors() }
}
intervalRows.sort((left, right) => left.sortKey < right.sortKey ? -1 : left.sortKey > right.sortKey ? 1 : 0)
